// The words of each calculator page, in English and in Spanish, written by hand. Every figure in a sentence is
// computed with the same functions as the calculator (src/tools/logic.ts), never typed.
import { DE_STATES, FR, fmt, type CountryData, type ToolData } from "../../src/tools/defs";
import { AREA_SOURCE, IMT, IRNR, NOTAIRE, SCHENGEN, SDLT, affordable, convertArea, fees, imt, irnrImputed, mortgageOrCash, notaireFr, rentYears, runningCosts, schengen, sdlt, sellAndMove } from "../../src/tools/logic";
import { esc, type Kit } from "../assetsKit";
import type { ToolPage } from "./kit";

export type Ctx = { k: Kit; today: string; c: Record<string, CountryData>; prices: Record<string, number[]>; nHomes: number; usTax: { n: number; medTax: number; min: number; max: number } | null };
const READ = "2026-11-14";

export function toolPages(x: Ctx): ToolPage[] {
  const { k } = x, { t } = k, f = fmt(k.lang);
  const eur = (n: number, d = 0) => f.money(n, "EUR", d), gbp = (n: number, d = 0) => f.money(n, "GBP", d);
  const costSrc = (label: string, key: string) => ({ label, url: `https://realhunt.co${k.es ? "/es" : ""}/costs/${key}` });
  const dataC: ToolData = { c: Object.fromEntries(Object.entries(x.c).map(([key, v]) => [key, { n: v.n, r: v.r, y: v.y }])) };
  const pages: ToolPage[] = [];

  // ------------------------------------------------------------ how much home a budget buys
  {
    const b = 100000, rows = Object.entries(x.c).map(([key, c]) => ({ key, c, a: affordable(b, c.r), pr: x.prices[key] || [] })).filter((r) => r.pr.length).map((r) => ({ ...r, homes: r.pr.filter((p) => p <= r.a.safe).length })).sort((p, q) => q.homes - p.homes);
    const total = rows.reduce((a, r) => a + r.homes, 0), top = rows[0], es0 = rows.find((r) => r.key === "spain") || rows[1];
    pages.push({
      tool: "budget", path: "/tools/how-much-home-can-i-buy", embed: "how-much-home-can-i-buy", data: { ...dataC, prices: x.prices, today: x.today }, read: READ,
      title: t("How much home can I buy? Budget calculator by country", "¿Qué casa puedo comprar? Calculadora por país"),
      h1: t("How much home can I buy abroad with my budget?", "¿Qué casa puedo comprar en el extranjero con mi presupuesto?"),
      desc: t(`Type your total budget and see, country by country, the highest price that fits once taxes and fees are paid, and how many homes on RealHunt cost that or less.`, `Escribe tu presupuesto total y mira, país por país, el precio máximo que encaja una vez pagados impuestos y gastos, y cuántas casas de RealHunt cuestan eso o menos.`),
      card: t("Your budget, minus each country's taxes and fees: what is left for the house and how many homes fit.", "Tu presupuesto, menos los impuestos y gastos de cada país: lo que queda para la casa y cuántas casas encajan."),
      lead: esc(t(`With ${eur(b)} in total, ${f.num(total)} of the ${f.num(x.nHomes)} homes on RealHunt fit once the taxes and fees of each country are paid. Most of them are in ${k.inThe(top.c.n)}: ${f.num(top.homes)} homes at ${eur(top.a.safe)} or less. Change the budget to see your own figure.`,
        `Con ${eur(b)} en total, encajan ${f.num(total)} de las ${f.num(x.nHomes)} casas de RealHunt una vez pagados los impuestos y gastos de cada país. La mayoría están en ${k.inThe(top.c.n)}: ${f.num(top.homes)} casas de ${eur(top.a.safe)} o menos. Cambia el presupuesto para ver tu cifra.`)),
      example: `<p>${esc(t(`Take a budget of ${eur(b)} and ${k.inThe(es0.c.n)}, where taxes and fees add ${f.pctRange(es0.c.r)} to the price. Dividing the budget by 1 plus the high end of that range gives ${eur(es0.a.safe)}: a home at that price still fits if the bill comes out at the top of the range. With the low end the limit would be ${eur(es0.a.best)}. RealHunt lists ${f.num(es0.homes)} homes in ${k.inThe(es0.c.n)} at ${eur(es0.a.safe)} or less today, out of ${f.num(es0.pr.length)}.`,
        `Toma un presupuesto de ${eur(b)} y ${k.inThe(es0.c.n)}, donde los impuestos y gastos añaden del ${f.pctRange(es0.c.r)} al precio. Dividir el presupuesto entre 1 más el extremo alto de ese rango da ${eur(es0.a.safe)}: una casa de ese precio sigue encajando aunque la factura salga por lo más alto. Con el extremo bajo, el límite sería ${eur(es0.a.best)}. RealHunt tiene hoy ${f.num(es0.homes)} casas en ${k.inThe(es0.c.n)} de ${eur(es0.a.safe)} o menos, de un total de ${f.num(es0.pr.length)}.`))}</p>`,
      how: [
        esc(t("Highest price that fits = budget ÷ (1 + the high end of the country's buying costs). The high end is used on purpose, so the answer errs on the safe side.", "Precio máximo que encaja = presupuesto ÷ (1 + el extremo alto de los gastos de compra del país). Se usa el extremo alto a propósito, para quedarse del lado prudente.")),
        esc(t(`Homes counted are the ones on RealHunt on ${k.date(x.today)}, each checked by a person, at their asking price in euros. It is not every home for sale in the country.`, `Las casas que se cuentan son las de RealHunt a ${k.date(x.today)}, revisadas una a una por una persona, a su precio de salida en euros. No son todas las casas en venta del país.`)),
        t(`Buying costs per country (transfer tax or VAT, notary, registry, lawyer) come from the <a href="/research/buying-costs-by-country">buying costs by country</a> table, with the sources of each one.`, `Los gastos de compra de cada país (impuesto de transmisiones o IVA, notaría, registro, abogado) salen de la tabla de <a href="/research/buying-costs-by-country">gastos de compra por país</a>, con las fuentes de cada uno.`),
        esc(t("Furniture, repairs, the move and the yearly running costs are not in the sum. Keep a reserve for them.", "No entran en la cuenta los muebles, las reformas, la mudanza ni los gastos anuales. Guarda una reserva para ellos.")),
      ],
      sources: [{ label: t("Buying costs by country, with sources (RealHunt)", "Gastos de compra por país, con fuentes (RealHunt)"), url: k.url("/research/buying-costs-by-country") }, { label: t("What each budget buys, by country (RealHunt data)", "Qué se compra con cada presupuesto, por país (datos de RealHunt)"), url: k.url("/research/what-your-budget-buys") }],
      faq: [
        [t("Why is the highest price lower than my budget?", "¿Por qué el precio máximo es menor que mi presupuesto?"), esc(t(`Because the price is not the whole bill. Transfer tax or VAT, the notary, the land registry and a lawyer add from ${f.pctRange(rows.slice().sort((p, q) => p.c.r[0] - q.c.r[0])[0].c.r)} in the cheapest country to ${f.pctRange(rows.slice().sort((p, q) => q.c.r[1] - p.c.r[1])[0].c.r)} in the dearest one, and they are paid in cash on the day you sign.`, `Porque el precio no es toda la factura. El impuesto de transmisiones o el IVA, la notaría, el registro y un abogado añaden desde el ${f.pctRange(rows.slice().sort((p, q) => p.c.r[0] - q.c.r[0])[0].c.r)} en el país más barato hasta el ${f.pctRange(rows.slice().sort((p, q) => q.c.r[1] - p.c.r[1])[0].c.r)} en el más caro, y se pagan al contado el día de la firma.`))],
        [t("Does the count include every home for sale?", "¿El recuento incluye todas las casas en venta?"), t(`No. It counts the homes RealHunt lists: cheap for their country, ready to live in and checked by a person. See <a href="/method">how homes are chosen and scored</a>.`, `No. Cuenta las casas que publica RealHunt: baratas para su país, listas para entrar a vivir y revisadas por una persona. Mira <a href="/method">cómo se eligen y se puntúan las casas</a>.`)],
        [t("Can I buy in every country on the list?", "¿Puedo comprar en todos los países de la lista?"), t(`Not always. Some countries ask for a permit or limit what a buyer from abroad can own. Check <a href="/research/where-foreigners-can-buy">where foreigners can buy</a> before you fall for a house.`, `No siempre. Algunos países piden un permiso o limitan lo que puede tener un comprador de fuera. Mira <a href="/research/where-foreigners-can-buy">dónde puede comprar un extranjero</a> antes de encapricharte de una casa.`)],
      ],
    });
  }

  // ------------------------------------------------------------ two countries side by side
  {
    const A = x.c.spain, B = x.c.italy, fa = fees(100000, A.r), fb = fees(100000, B.r);
    pages.push({
      tool: "compare", path: "/tools/compare-buying-costs", embed: "compare-buying-costs", data: dataC, read: READ,
      title: t("Compare the total cost of two homes in two countries", "Compara el coste total de dos casas en dos países"),
      h1: t("Compare the total cost of two homes in different countries", "Compara el coste total de dos casas en países distintos"),
      desc: t("Two homes, two countries: enter each price and see taxes and fees, the total for each and which one costs less once everything is paid. Free, with sources.", "Dos casas, dos países: escribe cada precio y mira los impuestos y gastos, el total de cada una y cuál sale más barata con todo pagado. Gratis y con fuentes."),
      card: t("Two homes in two countries: taxes, fees and total for each, side by side.", "Dos casas en dos países: impuestos, gastos y total de cada una, frente a frente."),
      lead: esc(t(`The same ${eur(100000)} home costs ${f.range(fa.totalLo, fa.totalHi)} in total in ${A.n} and ${f.range(fb.totalLo, fb.totalHi)} in ${B.n}, because taxes and fees are ${f.pctRange(A.r)} of the price in one and ${f.pctRange(B.r)} in the other. Pick your two countries and prices.`,
        `La misma casa de ${eur(100000)} cuesta en total de ${f.range(fa.totalLo, fa.totalHi)} en ${A.n} y de ${f.range(fb.totalLo, fb.totalHi)} en ${B.n}, porque los impuestos y gastos son del ${f.pctRange(A.r)} del precio en uno y del ${f.pctRange(B.r)} en el otro. Elige tus dos países y precios.`)),
      example: `<p>${esc(t(`A ${eur(90000)} flat in ${x.c.portugal.n} against a ${eur(100000)} house in ${x.c.greece.n}. ${x.c.portugal.n} adds ${f.pctRange(x.c.portugal.r)}: ${f.range(fees(90000, x.c.portugal.r).lo, fees(90000, x.c.portugal.r).hi)}, so ${f.range(fees(90000, x.c.portugal.r).totalLo, fees(90000, x.c.portugal.r).totalHi)} in total. ${x.c.greece.n} adds ${f.pctRange(x.c.greece.r)}: ${f.range(fees(100000, x.c.greece.r).lo, fees(100000, x.c.greece.r).hi)}, so ${f.range(fees(100000, x.c.greece.r).totalLo, fees(100000, x.c.greece.r).totalHi)}. The gap between the two price tags is ${eur(10000)}; the gap between the two bills is not the same number.`,
        `Un piso de ${eur(90000)} en ${x.c.portugal.n} frente a una casa de ${eur(100000)} en ${x.c.greece.n}. ${x.c.portugal.n} añade del ${f.pctRange(x.c.portugal.r)}: de ${f.range(fees(90000, x.c.portugal.r).lo, fees(90000, x.c.portugal.r).hi)}, así que de ${f.range(fees(90000, x.c.portugal.r).totalLo, fees(90000, x.c.portugal.r).totalHi)} en total. ${x.c.greece.n} añade del ${f.pctRange(x.c.greece.r)}: de ${f.range(fees(100000, x.c.greece.r).lo, fees(100000, x.c.greece.r).hi)}, así que de ${f.range(fees(100000, x.c.greece.r).totalLo, fees(100000, x.c.greece.r).totalHi)}. La diferencia entre los dos precios anunciados es de ${eur(10000)}; la diferencia entre las dos facturas no es la misma cifra.`))}</p>`,
      how: [
        esc(t("For each home: taxes and fees = price × the country's range of buying costs; total = price + taxes and fees. Both ends of the range are shown.", "Para cada casa: impuestos y gastos = precio × el rango de gastos de compra del país; total = precio + impuestos y gastos. Se muestran los dos extremos del rango.")),
        esc(t("The verdict compares the middle of each range. When the two ranges overlap it says so: the order can flip with a different region, a new build instead of a resale, or a dearer lawyer.", "El veredicto compara el punto medio de cada rango. Cuando los dos rangos se solapan lo dice: el orden puede invertirse con otra región, con obra nueva en vez de segunda mano o con un abogado más caro.")),
        t(`The ranges and what they are made of are in <a href="/research/buying-costs-by-country">buying costs by country</a>; each country page lists its sources.`, `Los rangos y su composición están en <a href="/research/buying-costs-by-country">gastos de compra por país</a>; la página de cada país enumera sus fuentes.`),
        esc(t("Prices are in euros. Yearly taxes, community fees and travel are a different sum: use the running costs calculator for them.", "Los precios van en euros. Los impuestos anuales, la comunidad y los viajes son otra cuenta: usa para ellos la calculadora de gastos anuales.")),
      ],
      sources: [{ label: t("Buying costs by country, with sources (RealHunt)", "Gastos de compra por país, con fuentes (RealHunt)"), url: k.url("/research/buying-costs-by-country") }],
      faq: [
        [t("Which country has the lowest buying costs?", "¿Qué país tiene los gastos de compra más bajos?"), t(`It depends on the kind of home, but the ranking by the middle of each range is in the <a href="/research/buying-costs-by-country">buying costs table</a>, from the lowest to the highest.`, `Depende del tipo de vivienda, pero la clasificación por el punto medio de cada rango está en la <a href="/research/buying-costs-by-country">tabla de gastos de compra</a>, de menor a mayor.`)],
        [t("Should I compare two specific homes instead?", "¿Y si quiero comparar dos casas concretas?"), t(`Yes, when you have them. <a href="/compare">Compare homes</a> puts two listings side by side with price, size, score and costs.`, `Sí, cuando las tengas. <a href="/compare">Comparar casas</a> pone dos anuncios frente a frente con precio, superficie, nota y gastos.`)],
        [t("Are agent fees included?", "¿Se incluyen los honorarios de la agencia?"), esc(t("Only where the buyer normally pays them and the country's range says so. In most countries on the list the seller pays the agent, and it is already inside the asking price.", "Solo donde los paga normalmente el comprador y el rango del país lo indica. En la mayoría de los países de la lista los paga el vendedor y ya van dentro del precio anunciado."))],
      ],
    });
  }

  // ------------------------------------------------------------ yearly cost of keeping a home
  {
    const d = { price: 80000, tax: 400, fees: 50, insurance: 250, utilities: 90, upkeep: 800, trips: 4, trip: 250, oneoff: 0, years: 5 };
    const r = runningCosts(d), m = (n: number) => f.num(n);
    const bg = runningCosts({ price: 30000, fees: 55 }), bgY = bg.yearsToPrice;
    const us = x.usTax;
    pages.push({
      tool: "running", path: "/tools/home-running-costs", embed: "home-running-costs", read: READ,
      data: { c: Object.fromEntries(Object.entries(x.c).filter(([, v]) => v.tax).map(([key, v]) => [key, v])) },
      title: t("Yearly cost of owning a home abroad: calculator", "Coste anual de tener una casa fuera: calculadora"),
      h1: t("What a home abroad costs to keep each year", "Lo que cuesta al año mantener una casa en el extranjero"),
      desc: t("Add up property tax, community or complex fees, insurance, bills, repairs and trips: the cost per year and per month, and how many years of costs equal the price.", "Suma impuesto anual, comunidad o cuota del complejo, seguro, suministros, reparaciones y viajes: el coste al año y al mes, y cuántos años de gastos igualan el precio."),
      card: t("Tax, fees, insurance, bills, repairs and trips: the cost per year, and the years of costs that equal the price.", "Impuesto, cuotas, seguro, suministros, reparaciones y viajes: el coste al año y los años de gastos que igualan el precio."),
      lead: esc(t(`A home that costs ${m(d.price)} to buy and ${m(r.year)} a year to keep costs ${m(r.month)} a month: ${f.pct(r.pct, 1)} of its price every year, so in ${f.trim(r.yearsToPrice, 1)} years the running costs add up to what you paid for it. Put in your own bills; the calculator shows the yearly property tax rule of each country next to them.`,
        `Una casa que cuesta ${m(d.price)} y ${m(r.year)} al año de mantener sale por ${m(r.month)} al mes: el ${f.pct(r.pct, 1)} de su precio cada año, así que en ${f.trim(r.yearsToPrice, 1)} años los gastos igualan lo que pagaste por ella. Pon tus propias facturas; la calculadora enseña al lado la norma del impuesto anual de cada país.`)),
      example: `<p>${esc(t(`The example in the calculator: property tax ${m(d.tax)} a year, community fees ${m(d.fees)} a month (${m(d.fees * 12)} a year), insurance ${m(d.insurance)}, power, water and internet ${m(d.utilities)} a month (${m(d.utilities * 12)}), repairs ${m(d.upkeep)} and four trips at ${m(d.trip)} each (${m(d.trips * d.trip)}). Total: ${m(r.year)} a year.`,
        `El ejemplo de la calculadora: impuesto anual de ${m(d.tax)}, comunidad de ${m(d.fees)} al mes (${m(d.fees * 12)} al año), seguro de ${m(d.insurance)}, luz, agua e internet por ${m(d.utilities)} al mes (${m(d.utilities * 12)}), reparaciones por ${m(d.upkeep)} y cuatro viajes de ${m(d.trip)} cada uno (${m(d.trips * d.trip)}). Total: ${m(r.year)} al año.`))}</p>`
        + `<p>${esc(t(`A flat in a holiday complex is the case where this sum matters most. With a yearly fee of ${m(660)} (${m(55)} a month) on a ${m(30000)} flat, and nothing else counted, the fees alone equal the price in ${f.trim(bgY, 1)} years. Ask for the fee per square metre and what it covers before you compare two complexes.`,
          `Un piso en un complejo de vacaciones es el caso en que más pesa esta cuenta. Con una cuota anual de ${m(660)} (${m(55)} al mes) en un piso de ${m(30000)}, y sin contar nada más, solo las cuotas igualan el precio en ${f.trim(bgY, 1)} años. Pregunta la cuota por metro cuadrado y qué cubre antes de comparar dos complejos.`))}</p>`
        + (us ? `<p>${esc(t(`A real reference from our own data: on the ${us.n} homes in the United States on RealHunt whose listing states the yearly property tax bill, the median bill is ${f.money(us.medTax, "USD")}, from ${f.money(us.min, "USD")} to ${f.money(us.max, "USD")} (${k.date(x.today)}; the bill of a new owner can differ from the seller's).`,
          `Una referencia real de nuestros datos: en las ${us.n} casas de Estados Unidos de RealHunt cuyo anuncio indica el recibo anual del impuesto sobre la propiedad, el recibo mediano es de ${f.money(us.medTax, "USD")}, entre ${f.money(us.min, "USD")} y ${f.money(us.max, "USD")} (${k.date(x.today)}; el recibo de un nuevo propietario puede ser distinto del que paga el vendedor).`))}</p>` : ""),
      how: [
        esc(t("Per year = property tax + 12 × community fees + insurance + 12 × bills + repairs + trips × cost of a trip + the one-off bill ÷ the years you spread it over.", "Al año = impuesto anual + 12 × comunidad + seguro + 12 × suministros + reparaciones + viajes × coste de un viaje + el gasto puntual ÷ los años en que lo repartes.")),
        esc(t("Share of the price = cost per year ÷ price. Years of costs that equal the price = price ÷ cost per year.", "Parte del precio = coste anual ÷ precio. Años de gastos que igualan el precio = precio ÷ coste anual.")),
        esc(t("All figures are yours: the calculator has no rate of its own. Choose a country to read how its yearly property tax is set, with the sources on its cost page.", "Todas las cifras son tuyas: la calculadora no tiene ningún tipo propio. Elige un país para leer cómo se fija su impuesto anual, con las fuentes en su página de gastos.")),
        esc(t("A one-off bill (a special assessment in a block of flats, a roof, a boiler) is spread over the years you choose, so one bad year does not hide in the average.", "Un gasto puntual (una derrama del edificio, un tejado, una caldera) se reparte en los años que elijas, para que un mal año no quede escondido en la media.")),
      ],
      sources: [{ label: t("Yearly property tax by country, with sources (RealHunt)", "Impuesto anual por país, con fuentes (RealHunt)"), url: k.url("/research/buying-costs-by-country") }, { label: t("Costs, taxes and sources by country (RealHunt)", "Gastos, impuestos y fuentes por país (RealHunt)"), url: k.url("/costs") }],
      faq: [
        [t("What does it cost per year to own a cheap home abroad?", "¿Cuánto cuesta al año tener una casa barata en el extranjero?"), esc(t(`There is no single figure: it depends on the tax of the town, the building and how often you go. The example above, ${m(r.year)} a year on a ${m(d.price)} home, is ${f.pct(r.pct, 1)} of the price, and travel is ${f.pct((r.lines.travel / r.year) * 100, 0)} of it.`, `No hay una cifra única: depende del impuesto del municipio, del edificio y de cuánto vayas. El ejemplo de arriba, ${m(r.year)} al año en una casa de ${m(d.price)}, es el ${f.pct(r.pct, 1)} del precio, y los viajes son el ${f.pct((r.lines.travel / r.year) * 100, 0)} de esa cifra.`))],
        [t("How do I know the community or complex fee before buying?", "¿Cómo sé la cuota de comunidad o del complejo antes de comprar?"), esc(t("Ask the seller or the agent for the last yearly statement of the building and the minutes of the last owners' meeting. They show the fee, any debt of the flat and the works already voted.", "Pide al vendedor o a la agencia la última liquidación anual del edificio y el acta de la última junta de propietarios. Ahí aparecen la cuota, las deudas del piso y las obras ya aprobadas."))],
        [t("Is the cost of travelling really part of it?", "¿De verdad cuentan los viajes?"), esc(t("For a second home, yes. Four return trips a year with a hire car often cost more than the property tax. Set trips to zero if you will live there.", "En una segunda residencia, sí. Cuatro viajes de ida y vuelta al año con coche de alquiler suelen costar más que el impuesto anual. Pon los viajes a cero si vas a vivir allí."))],
      ],
    });
  }

  // ------------------------------------------------------------ United Kingdom
  {
    const p = 250000, nr = sdlt(p, { nonResident: true }), res = sdlt(p), both = sdlt(p, { nonResident: true, additional: true }), low = sdlt(100000, { nonResident: true });
    pages.push({
      tool: "sdlt", path: "/tools/uk-stamp-duty-non-resident", embed: "uk-stamp-duty-non-resident", data: {}, read: SDLT.read,
      title: t("UK stamp duty calculator for non-residents", "Impuesto de compra en Reino Unido para no residentes"),
      h1: t("Stamp duty calculator for non-UK residents buying in England", "Calculadora del impuesto de compra en Inglaterra para no residentes"),
      desc: t(`Stamp Duty Land Tax for a buyer who does not live in the UK: the standard bands plus the 2% surcharge, and 5% more if you own another home. ${gbp(p)} home: ${gbp(nr.tax)}.`, `El impuesto de compra de una vivienda en Inglaterra para quien no vive en el Reino Unido: tramos generales, recargo del 2 % y 5 % más con otra vivienda. Casa de ${gbp(p)}: ${gbp(nr.tax)}.`),
      card: t("Stamp Duty Land Tax in England and Northern Ireland with the 2% non-resident surcharge.", "El impuesto de compra de Inglaterra e Irlanda del Norte con el recargo del 2 % a no residentes."),
      lead: esc(t(`A buyer who is not resident in the UK pays ${gbp(nr.tax)} of Stamp Duty Land Tax on a ${gbp(p)} home in England or Northern Ireland, against ${gbp(res.tax)} for a UK resident: the non-resident surcharge adds 2 points to every band. If you already own a home anywhere in the world, 5 more points apply and the bill is ${gbp(both.tax)}.`,
        `Un comprador que no reside en el Reino Unido paga ${gbp(nr.tax)} de impuesto de compra (Stamp Duty Land Tax) por una casa de ${gbp(p)} en Inglaterra o Irlanda del Norte, frente a ${gbp(res.tax)} de un residente: el recargo a no residentes suma 2 puntos a cada tramo. Si ya tienes una vivienda en cualquier país, se añaden 5 puntos más y la factura es de ${gbp(both.tax)}.`)),
      example: `<p>${esc(t(`${gbp(p)}, non-resident, no other home. The first ${gbp(125000)} is taxed at 2% (0% plus the surcharge): ${gbp(2500)}. The next ${gbp(125000)} is taxed at 4% (2% plus the surcharge): ${gbp(5000)}. Total ${gbp(nr.tax)}, ${f.pct(nr.effective, 1)} of the price. On a ${gbp(100000)} home the standard rate is zero, but the surcharge still applies: ${gbp(low.tax)}.`,
        `${gbp(p)}, no residente, sin otra vivienda. Las primeras ${gbp(125000)} tributan al 2 % (0 % más el recargo): ${gbp(2500)}. Las siguientes ${gbp(125000)} tributan al 4 % (2 % más el recargo): ${gbp(5000)}. Total: ${gbp(nr.tax)}, el ${f.pct(nr.effective, 1)} del precio. En una casa de ${gbp(100000)} el tipo general es cero, pero el recargo se aplica igual: ${gbp(low.tax)}.`))}</p>`,
      how: [
        esc(t(`Standard residential bands, in force since 1 April 2025: 0% up to ${gbp(125000)}, 2% from ${gbp(125001)} to ${gbp(250000)}, 5% up to ${gbp(925000)}, 10% up to ${gbp(1500000)} and 12% above. Each rate applies only to the slice of the price inside its band.`, `Tramos generales para vivienda, vigentes desde el 1 de abril de 2025: 0 % hasta ${gbp(125000)}, 2 % de ${gbp(125001)} a ${gbp(250000)}, 5 % hasta ${gbp(925000)}, 10 % hasta ${gbp(1500000)} y 12 % por encima. Cada tipo se aplica solo a la parte del precio que cae en su tramo.`)),
        esc(t("Non-resident surcharge: 2 points on top of every band, since 1 April 2021. You count as non-resident for the purchase if you were in the UK fewer than 183 days in the 12 months before it.", "Recargo a no residentes: 2 puntos sobre cada tramo, desde el 1 de abril de 2021. Cuentas como no residente para la compra si estuviste en el Reino Unido menos de 183 días en los 12 meses anteriores.")),
        esc(t("Additional home: usually 5 points on top of every band if you own another residential property. The two surcharges add up.", "Vivienda adicional: normalmente 5 puntos sobre cada tramo si tienes otra vivienda. Los dos recargos se suman.")),
        esc(t("The 2% can be refunded if you then spend at least 183 days in the UK in a continuous 365-day period within the two years the rules set; the claim is made by amending the return.", "El 2 % puede devolverse si después pasas al menos 183 días en el Reino Unido en un periodo continuo de 365 días dentro de los dos años que fija la norma; se pide modificando la declaración.")),
        esc(t("Scotland and Wales have their own taxes and are not covered. First-time buyer relief is not applied here.", "Escocia y Gales tienen sus propios impuestos y no se incluyen. La bonificación para primera vivienda no se aplica aquí.")),
      ],
      sources: [{ label: t("GOV.UK, Stamp Duty Land Tax: residential property rates", "GOV.UK, impuesto de compra: tipos para vivienda"), url: SDLT.sources[0] }, { label: t("GOV.UK, rates of Stamp Duty Land Tax for non-UK residents", "GOV.UK, tipos del impuesto de compra para no residentes"), url: SDLT.sources[1] }, costSrc(t("Other costs of buying in the United Kingdom (RealHunt)", "Otros gastos de comprar en el Reino Unido (RealHunt)"), "united-kingdom")],
      faq: [
        [t("Do foreigners pay more stamp duty in the UK?", "¿Pagan más impuesto de compra los extranjeros en el Reino Unido?"), esc(t(`Nationality does not matter; residence does. A buyer of any passport who was in the UK fewer than 183 days in the 12 months before buying pays 2 points more on every band in England and Northern Ireland: ${gbp(nr.tax - res.tax)} more on a ${gbp(p)} home.`, `No importa la nacionalidad, sino la residencia. Un comprador con cualquier pasaporte que haya estado en el Reino Unido menos de 183 días en los 12 meses anteriores paga 2 puntos más en cada tramo en Inglaterra e Irlanda del Norte: ${gbp(nr.tax - res.tax)} más en una casa de ${gbp(p)}.`))],
        [t("Is there stamp duty on a home under £125,000?", "¿Se paga impuesto por una casa de menos de 125.000 libras?"), esc(t(`For a UK resident with no other home, no. A non-resident pays 2% from the first pound (${gbp(low.tax)} on ${gbp(100000)}), and a buyer who owns another home pays 5% more on top.`, `Un residente sin otra vivienda, no. Un no residente paga el 2 % desde la primera libra (${gbp(low.tax)} sobre ${gbp(100000)}), y quien ya tiene otra vivienda paga además un 5 % más.`))],
        [t("When is it paid?", "¿Cuándo se paga?"), t(`Your solicitor normally files the return and pays it for you on completion. The other costs of the purchase are on the <a href="/buying-costs/united-kingdom">UK buying costs page</a>.`, `Lo habitual es que tu abogado presente la declaración y lo pague por ti al completar la compra. Los demás gastos están en la <a href="/buying-costs/united-kingdom">página de gastos de compra del Reino Unido</a>.`)],
      ],
    });
  }

  // ------------------------------------------------------------ Portugal
  {
    const p = 200000, o = imt(p, "mainland", "other"), own = imt(p, "mainland", "own"), st = p * 0.008, cheap = imt(90000, "mainland", "other");
    pages.push({
      tool: "imt", path: "/tools/portugal-imt", embed: "portugal-imt", data: {}, read: IMT.read,
      title: t(`Portugal IMT calculator ${IMT.year}: property transfer tax`, `Calculadora del IMT de Portugal ${IMT.year}`),
      h1: t(`Portugal IMT calculator: transfer tax on a home (${IMT.year} tables)`, `Calculadora del IMT de Portugal: impuesto de compra de una vivienda (tablas de ${IMT.year})`),
      desc: t(`IMT and stamp duty on a home in Portugal with the official ${IMT.year} tables: second home or own home, mainland or islands. ${eur(p)} second home: ${eur(o.tax, 2)} of IMT.`, `IMT e impuesto del sello de una vivienda en Portugal con las tablas oficiales de ${IMT.year}: segunda o primera residencia, continente o islas. Segunda residencia de ${eur(p)}: ${eur(o.tax, 2)}.`),
      card: t(`IMT and stamp duty with the official ${IMT.year} tables, mainland and islands.`, `IMT e impuesto del sello con las tablas oficiales de ${IMT.year}, continente e islas.`),
      lead: esc(t(`A ${eur(p)} home in mainland Portugal bought as a second home, a holiday home or to let pays ${eur(o.tax, 2)} of IMT (the property transfer tax) plus ${eur(st, 2)} of stamp duty: ${eur(o.tax + st, 2)} in the two taxes. Bought as your own permanent home the IMT is ${eur(own.tax, 2)}. The tables below are the ${IMT.year} ones.`,
        `Una vivienda de ${eur(p)} en Portugal continental comprada como segunda residencia, para vacaciones o para alquilar paga ${eur(o.tax, 2)} de IMT (el impuesto de transmisiones) más ${eur(st, 2)} de impuesto del sello: ${eur(o.tax + st, 2)} entre los dos. Comprada como vivienda habitual, el IMT es de ${eur(own.tax, 2)}. Las tablas de abajo son las de ${IMT.year}.`)),
      example: `<p>${esc(t(`${eur(p)}, mainland, second home. The price falls in the band from ${eur(198347)} to ${eur(330539)}: marginal rate 7%, amount to subtract ${eur(9394.5, 2)}. IMT = ${eur(p)} × 7% − ${eur(9394.5, 2)} = ${eur(o.tax, 2)}. Stamp duty = ${eur(p)} × 0.8% = ${eur(st, 2)}. A ${eur(90000)} flat, also as a second home, stays in the first band at 1%: ${eur(cheap.tax, 2)} of IMT.`,
        `${eur(p)}, continente, segunda residencia. El precio cae en el tramo de ${eur(198347)} a ${eur(330539)}: tipo marginal del 7 %, cantidad a restar de ${eur(9394.5, 2)}. IMT = ${eur(p)} × 7 % − ${eur(9394.5, 2)} = ${eur(o.tax, 2)}. Impuesto del sello = ${eur(p)} × 0,8 % = ${eur(st, 2)}. Un piso de ${eur(90000)}, también como segunda residencia, se queda en el primer tramo, al 1 %: ${eur(cheap.tax, 2)} de IMT.`))}</p>`,
      how: [
        esc(t(`IMT = price × the marginal rate of its band − the amount to subtract of that band. Above ${eur(1150853)} on the mainland a single rate of 7.5% applies to the whole price, and 6% in the band just below it.`, `IMT = precio × el tipo marginal de su tramo − la cantidad a restar de ese tramo. Por encima de ${eur(1150853)} en el continente se aplica un tipo único del 7,5 % a todo el precio, y del 6 % en el tramo inmediatamente inferior.`)),
        esc(t(`Second home, holiday home or home to let (mainland): 1% up to ${eur(106346)}, then 2%, 5%, 7% and 8%. Own permanent home (mainland): 0% up to ${eur(106346)}, then the same marginal rates.`, `Segunda residencia, vacaciones o alquiler (continente): 1 % hasta ${eur(106346)}, y después 2 %, 5 %, 7 % y 8 %. Vivienda habitual (continente): 0 % hasta ${eur(106346)}, y después los mismos tipos marginales.`)),
        esc(t(`Madeira and the Azores use the same rates with higher bands (the first one ends at ${eur(132933)}).`, `Madeira y las Azores usan los mismos tipos con tramos más altos (el primero termina en ${eur(132933)}).`)),
        esc(t("The tax is charged on the price in the deed or on the tax value of the property, whichever is higher. The calculator uses the price you type.", "El impuesto se calcula sobre el precio de la escritura o sobre el valor fiscal del inmueble, el que sea mayor. La calculadora usa el precio que escribes.")),
        esc(t("Stamp duty of 0.8% of the price is added. The exemption for buyers aged 35 or under who buy their first permanent home is not applied here.", "Se añade el impuesto del sello, el 0,8 % del precio. No se aplica aquí la exención para menores de 36 años que compran su primera vivienda habitual.")),
      ],
      sources: [{ label: t(`Portuguese tax authority, circular 40129/2026 of 6 January 2026: IMT tables in force from 1 January ${IMT.year}`, `Autoridad tributaria portuguesa, oficio circulado 40129/2026 de 6 de enero de 2026: tablas del IMT vigentes desde el 1 de enero de ${IMT.year}`), url: IMT.source }, costSrc(t("Stamp duty and the other costs of buying in Portugal (RealHunt)", "Impuesto del sello y demás gastos de comprar en Portugal (RealHunt)"), "portugal")],
      faq: [
        [t("Do foreigners pay a different IMT in Portugal?", "¿Pagan los extranjeros un IMT distinto en Portugal?"), esc(t("The tables do not depend on nationality. What changes the tax is the use: a buyer who will not live in the home as a permanent residence, which is the usual case for a buyer from abroad, uses the table without the 0% band.", "Las tablas no dependen de la nacionalidad. Lo que cambia el impuesto es el uso: quien no va a vivir en la casa de forma permanente, que es lo habitual en un comprador de fuera, usa la tabla sin tramo al 0 %."))],
        [t("How much is IMT on a €100,000 home?", "¿Cuánto es el IMT de una casa de 100.000 €?"), esc(t(`As a second home on the mainland: ${eur(imt(100000, "mainland", "other").tax, 2)} (1%), plus ${eur(800)} of stamp duty. As your own permanent home: ${eur(imt(100000, "mainland", "own").tax, 2)} of IMT, and the stamp duty still applies.`, `Como segunda residencia en el continente: ${eur(imt(100000, "mainland", "other").tax, 2)} (1 %), más ${eur(800)} de impuesto del sello. Como vivienda habitual: ${eur(imt(100000, "mainland", "own").tax, 2)} de IMT, y el impuesto del sello se paga igual.`))],
        [t("What else do I pay when buying in Portugal?", "¿Qué más se paga al comprar en Portugal?"), t(`Notary, land registry and a lawyer. The full range is on the <a href="/buying-costs/portugal">Portugal buying costs page</a>.`, `Notaría, registro y abogado. El rango completo está en la <a href="/buying-costs/portugal">página de gastos de compra de Portugal</a>.`)],
      ],
    });
  }

  // ------------------------------------------------------------ France
  {
    const p = 150000, hi = notaireFr(p, { duties: 6.3, csi: FR.csi, debours: FR.debours }), lo = notaireFr(p, { duties: 5.8, csi: FR.csi, debours: FR.debours }), small = notaireFr(60000, { duties: 6.3, csi: FR.csi, debours: FR.debours });
    pages.push({
      tool: "notaire", path: "/tools/france-notary-fees", embed: "france-notary-fees", data: {}, read: NOTAIRE.read,
      title: t("French notary fees calculator for a resale home", "Calculadora de gastos de notaría en Francia"),
      h1: t("Notary fees calculator for buying a resale home in France", "Calculadora de gastos de notaría al comprar una vivienda de segunda mano en Francia"),
      desc: t(`What the notary collects when you buy a resale home in France: transfer duties, the regulated fee with VAT, the registry contribution and disbursements. ${eur(p)} home: ${f.range(hi.lo, hi.hi)}.`, `Lo que cobra el notario al comprar una vivienda de segunda mano en Francia: derechos de transmisión, arancel con IVA, registro y suplidos. Casa de ${eur(p)}: de ${f.range(hi.lo, hi.hi)}.`),
      card: t("Transfer duties, the notary's regulated fee with VAT, the registry contribution and disbursements.", "Derechos de transmisión, arancel regulado del notario con IVA, contribución de registro y suplidos."),
      lead: esc(t(`On a ${eur(p)} resale home in France the "notary fees" come to ${f.range(hi.lo, hi.hi)}, about ${f.trim(hi.pctLo, 1)} to ${f.pct(hi.pctHi, 1)} of the price, in a department that charges transfer duties of about 6.3%. Most of it is tax: ${eur(hi.duties, 2)} of duties against ${eur(hi.emol + hi.vat, 2)} for the notary's own fee with VAT.`,
        `En una vivienda de segunda mano de ${eur(p)} en Francia, los «gastos de notaría» suman de ${f.range(hi.lo, hi.hi)}, entre el ${f.trim(hi.pctLo, 1)} y el ${f.pct(hi.pctHi, 1)} del precio, en un departamento con derechos de transmisión de alrededor del 6,3 %. Casi todo es impuesto: ${eur(hi.duties, 2)} de derechos frente a ${eur(hi.emol + hi.vat, 2)} del arancel del notario con IVA.`)),
      example: `<p>${esc(t(`${eur(p)} at about 6.3%. Transfer duties: ${eur(hi.duties, 2)}. Notary's regulated fee: 3.870% of the first ${eur(6500)} (${eur(251.55, 2)}), 1.596% of the next ${eur(10500)} (${eur(167.58, 2)}), 1.064% of the next ${eur(43000)} (${eur(457.52, 2)}) and 0.799% of the remaining ${eur(90000)} (${eur(719.1, 2)}): ${eur(hi.emol, 2)}, plus 20% VAT, ${eur(hi.vat, 2)}. Land-registry contribution at 0.10%: ${eur(hi.csi, 2)}. With disbursements of about ${f.range(FR.debours[0], FR.debours[1])}, the total is ${f.range(hi.lo, hi.hi)}. In a department at about 5.8% it is ${f.range(lo.lo, lo.hi)}.`,
        `${eur(p)} con alrededor del 6,3 %. Derechos de transmisión: ${eur(hi.duties, 2)}. Arancel regulado del notario: 3,870 % de los primeros ${eur(6500)} (${eur(251.55, 2)}), 1,596 % de los siguientes ${eur(10500)} (${eur(167.58, 2)}), 1,064 % de los siguientes ${eur(43000)} (${eur(457.52, 2)}) y 0,799 % de los ${eur(90000)} restantes (${eur(719.1, 2)}): ${eur(hi.emol, 2)}, más el 20 % de IVA, ${eur(hi.vat, 2)}. Contribución de seguridad inmobiliaria al 0,10 %: ${eur(hi.csi, 2)}. Con unos suplidos de ${f.range(FR.debours[0], FR.debours[1])}, el total es de ${f.range(hi.lo, hi.hi)}. En un departamento con alrededor del 5,8 % es de ${f.range(lo.lo, lo.hi)}.`))}</p>`,
      how: [
        esc(t("Transfer duties (droits de mutation): about 5.8% of the price, or about 6.3% in the departments that raised their rate for 2025 to March 2028. The notary collects them for the state and the local authorities.", "Derechos de transmisión (droits de mutation): alrededor del 5,8 % del precio, o del 6,3 % en los departamentos que subieron su tipo entre 2025 y marzo de 2028. El notario los cobra para el Estado y las entidades locales.")),
        esc(t(`Notary's regulated fee (émoluments), scale in force since 1 January 2021 in mainland France: 3.870% up to ${eur(6500)}, 1.596% from ${eur(6500)} to ${eur(17000)}, 1.064% from ${eur(17000)} to ${eur(60000)} and 0.799% above, plus 20% VAT.`, `Arancel regulado del notario (émoluments), escala vigente desde el 1 de enero de 2021 en la Francia continental: 3,870 % hasta ${eur(6500)}, 1,596 % de ${eur(6500)} a ${eur(17000)}, 1,064 % de ${eur(17000)} a ${eur(60000)} y 0,799 % por encima, más el 20 % de IVA.`)),
        esc(t(`Land-registry contribution (contribution de sécurité immobilière): 0.10% of the price. Disbursements (débours), what the notary pays to third parties for you: about ${f.range(FR.debours[0], FR.debours[1])}.`, `Contribución de seguridad inmobiliaria (contribution de sécurité immobilière): 0,10 % del precio. Suplidos (débours), lo que el notario paga a terceros por tu cuenta: de ${f.range(FR.debours[0], FR.debours[1])} aproximadamente.`)),
        esc(t("For a resale home. A new build bought from a developer pays VAT inside the price and much lower duties, so its notary fees are a smaller share. The overseas departments have their own scales.", "Para vivienda de segunda mano. La obra nueva comprada a un promotor paga el IVA dentro del precio y unos derechos mucho más bajos, así que sus gastos de notaría son una parte menor. Los departamentos de ultramar tienen sus propias escalas.")),
      ],
      sources: [{ label: t("Service-Public.fr (French administration), notary fees: scale of the regulated fee, checked by the site on 5 August 2026", "Service-Public.fr (administración francesa), gastos de notaría: escala del arancel, revisada por el sitio el 5 de agosto de 2026"), url: NOTAIRE.source }, costSrc(t("Transfer duties, registry contribution and disbursements in France, with sources (RealHunt)", "Derechos de transmisión, contribución de registro y suplidos en Francia, con fuentes (RealHunt)"), "france")],
      faq: [
        [t("Why are notary fees a bigger share on a cheap home?", "¿Por qué los gastos de notaría pesan más en una casa barata?"), esc(t(`Because the scale starts at 3.870% and falls as the price rises, and the disbursements are a fixed amount. On a ${eur(60000)} home the total is ${f.range(small.lo, small.hi)}, ${f.trim(small.pctLo, 1)} to ${f.pct(small.pctHi, 1)} of the price, against ${f.trim(hi.pctLo, 1)} to ${f.pct(hi.pctHi, 1)} on ${eur(p)}.`, `Porque la escala empieza en el 3,870 % y baja a medida que sube el precio, y los suplidos son una cantidad fija. En una casa de ${eur(60000)} el total es de ${f.range(small.lo, small.hi)}, entre el ${f.trim(small.pctLo, 1)} y el ${f.pct(small.pctHi, 1)} del precio, frente al ${f.trim(hi.pctLo, 1)} a ${f.pct(hi.pctHi, 1)} con ${eur(p)}.`))],
        [t("Who pays the notary in France, buyer or seller?", "¿Quién paga al notario en Francia, el comprador o el vendedor?"), esc(t("The buyer. The agent's commission is a separate matter: it is usually already inside the advertised price and paid by the seller.", "El comprador. La comisión de la agencia es otra cosa: normalmente ya va dentro del precio anunciado y la paga el vendedor."))],
        [t("Is the notary's fee negotiable?", "¿Se puede negociar el arancel del notario?"), esc(t("The scale is set by law. Above a certain amount the notary may grant a discount on his own fee, the same for all his clients; the duties, which are most of the bill, cannot be reduced.", "La escala la fija la ley. A partir de cierto importe, el notario puede conceder una rebaja de su propio arancel, la misma para todos sus clientes; los derechos, que son casi toda la factura, no se pueden reducir."))],
      ],
    });
  }

  // ------------------------------------------------------------ Germany
  {
    const p = 150000, by = p * 0.035, hi = p * 0.065;
    const names = DE_STATES.filter((s) => s[1] === 6.5).map((s) => (k.es ? s[3] : s[2]));
    pages.push({
      tool: "grest", path: "/tools/germany-property-transfer-tax", embed: "germany-property-transfer-tax", data: {}, read: READ,
      title: t("Germany property transfer tax calculator by state", "Impuesto de compra en Alemania por estado federado"),
      h1: t("Property transfer tax calculator for Germany, by federal state", "Calculadora del impuesto de compra de una vivienda en Alemania, por estado federado"),
      desc: t(`Real estate transfer tax (Grunderwerbsteuer) on a home in Germany: 3.5% to 6.5% of the price depending on the state. ${eur(p)} home: ${eur(by)} in Bavaria, ${eur(hi)} at 6.5%.`, `El impuesto de compra de una vivienda en Alemania (Grunderwerbsteuer): del 3,5 % al 6,5 % del precio según el estado federado. Casa de ${eur(p)}: ${eur(by)} en Baviera y ${eur(hi)} al 6,5 %.`),
      card: t("Transfer tax of 3.5% to 6.5% of the price, depending on the federal state.", "Impuesto de compra del 3,5 % al 6,5 % del precio, según el estado federado."),
      lead: esc(t(`The German real estate transfer tax is a single rate on the whole price, and each federal state sets its own between 3.5% and 6.5%. On a ${eur(p)} home that is ${eur(by)} in Bavaria (3.5%) and ${eur(hi)} in ${k.list(names)} (6.5%): a gap of ${eur(hi - by)} for the same price.`,
        `El impuesto alemán de compra de inmuebles es un tipo único sobre todo el precio, y cada estado federado fija el suyo entre el 3,5 % y el 6,5 %. En una casa de ${eur(p)} son ${eur(by)} en Baviera (3,5 %) y ${eur(hi)} en ${k.list(names)} (6,5 %): ${eur(hi - by)} de diferencia por el mismo precio.`)),
      example: `<p>${esc(t(`A ${eur(80000)} flat in North Rhine-Westphalia: ${eur(80000)} × 6.5% = ${eur(5200)}. The same flat in Bavaria: ${eur(80000)} × 3.5% = ${eur(2800)}. Notary and land registry add about 1.5% to 2% in both, ${f.range(1200, 1600)}. If the seller hired the estate agent, the buyer pays half of the commission by law, on top of that.`,
        `Un piso de ${eur(80000)} en Renania del Norte-Westfalia: ${eur(80000)} × 6,5 % = ${eur(5200)}. El mismo piso en Baviera: ${eur(80000)} × 3,5 % = ${eur(2800)}. Notaría y registro añaden alrededor de un 1,5 % a un 2 % en los dos casos, de ${f.range(1200, 1600)}. Si la agencia la contrató el vendedor, el comprador paga por ley la mitad de la comisión, aparte.`))}</p>`,
      how: [
        esc(t("Tax = price × the rate of the state where the home is. There are no bands and no surcharge for buyers from abroad.", "Impuesto = precio × el tipo del estado donde está la vivienda. No hay tramos ni recargo para compradores extranjeros.")),
        esc(t(`Rates in our data: 3.5% in Bavaria; 6.5% in ${k.list(names)}. The other states sit between those two figures: choose "another state" and the rate printed on your notary's draft contract.`, `Tipos en nuestros datos: 3,5 % en Baviera; 6,5 % en ${k.list(names)}. Los demás estados están entre esas dos cifras: elige «otro estado» y el tipo que figure en el borrador del contrato del notario.`)),
        esc(t("The tax office sends the bill after the contract is signed at the notary; the buyer is entered in the land register only once it is paid.", "La oficina tributaria envía la liquidación tras la firma del contrato ante notario; el comprador solo se inscribe en el registro cuando está pagada.")),
        esc(t("Furniture and other movable items listed separately in the contract are not part of the taxable price; ask the notary how to state them.", "Los muebles y otros bienes muebles que consten por separado en el contrato no forman parte del precio gravado; pregunta al notario cómo indicarlos.")),
      ],
      sources: [{ label: t("German Bundestag, printed paper 21/5776 of 6 May 2026: the tax is 3.5% to 6.5% of the price depending on the state", "Parlamento alemán (Bundestag), documento 21/5776 de 6 de mayo de 2026: el impuesto es del 3,5 % al 6,5 % del precio según el estado"), url: "https://dserver.bundestag.de/btd/21/057/2105776.pdf" }, costSrc(t("Rates by state and the other costs of buying in Germany, with sources (RealHunt)", "Tipos por estado y demás gastos de comprar en Alemania, con fuentes (RealHunt)"), "germany")],
      faq: [
        [t("Which German state has the lowest property transfer tax?", "¿Qué estado alemán tiene el impuesto de compra más bajo?"), esc(t(`Bavaria, at 3.5%. The highest rate, 6.5%, applies in ${k.list(names)}.`, `Baviera, con el 3,5 %. El tipo más alto, el 6,5 %, se aplica en ${k.list(names)}.`))],
        [t("Do foreigners pay more?", "¿Pagan más los extranjeros?"), t(`No. The rate is the same for every buyer, and Germany does not restrict purchases by foreigners. See <a href="/guide/germany">how to buy in Germany</a>.`, `No. El tipo es el mismo para cualquier comprador, y Alemania no restringe la compra a extranjeros. Mira <a href="/guide/germany">cómo comprar en Alemania</a>.`)],
        [t("What is the total cost of buying in Germany?", "¿Cuál es el coste total de comprar en Alemania?"), t(`Transfer tax plus notary and land registry, and often half of the agent's commission. The range is on the <a href="/buying-costs/germany">Germany buying costs page</a>.`, `Impuesto de compra más notaría y registro, y a menudo la mitad de la comisión de la agencia. El rango está en la <a href="/buying-costs/germany">página de gastos de compra de Alemania</a>.`)],
      ],
    });
  }

  // ------------------------------------------------------------ Spain
  {
    const a = irnrImputed({ cadastral: 40000, revised: true, eea: true }), b = irnrImputed({ cadastral: 40000, revised: true, eea: false }), c2 = irnrImputed({ cadastral: 40000, revised: false, eea: false }), half = irnrImputed({ cadastral: 40000, revised: true, eea: true, days: 183 });
    pages.push({
      tool: "irnr", path: "/tools/spain-non-resident-tax", embed: "spain-non-resident-tax", data: {}, read: IRNR.read,
      title: t("Spain non-resident property tax calculator (form 210)", "Calculadora del impuesto de no residentes en España"),
      h1: t("Non-resident tax calculator for a home in Spain you do not let", "Calculadora del impuesto de no residentes por una vivienda en España que no alquilas"),
      desc: t(`The yearly tax a non-resident owner pays in Spain on a home kept for own use (form 210): 1.1% or 2% of the cadastral value, taxed at 19% or 24%. Example: ${eur(a.tax, 2)}.`, `El impuesto anual del propietario no residente en España por una vivienda de uso propio (modelo 210): el 1,1 % o el 2 % del valor catastral, al 19 % o al 24 %. Ejemplo: ${eur(a.tax, 2)}.`),
      card: t("Imputed income of a home for own use: 1.1% or 2% of the cadastral value, taxed at 19% or 24%.", "Renta imputada de una vivienda de uso propio: el 1,1 % o el 2 % del valor catastral, al 19 % o al 24 %."),
      lead: esc(t(`An owner who does not live in Spain pays income tax every year on a home there even if it earns nothing. With a cadastral value of ${eur(40000)} the bill is ${eur(a.tax, 2)} for a resident of the EU, Iceland, Norway or Liechtenstein and ${eur(b.tax, 2)} for anyone else. Type the cadastral value printed on your IBI bill.`,
        `Un propietario que no vive en España paga cada año impuesto sobre la renta por una vivienda allí aunque no le dé ningún ingreso. Con un valor catastral de ${eur(40000)}, la cuota es de ${eur(a.tax, 2)} para un residente en la UE, Islandia, Noruega o Liechtenstein y de ${eur(b.tax, 2)} para los demás. Escribe el valor catastral que figura en tu recibo del IBI.`)),
      example: `<p>${esc(t(`Cadastral value ${eur(40000)}, in a town that revised its values in the last ten years, owned all year. Imputed income: ${eur(40000)} × 1.1% = ${eur(a.base, 2)}. Tax for an EU resident: ${eur(a.base, 2)} × 19% = ${eur(a.tax, 2)}. For a resident of the United Kingdom or the United States: ${eur(a.base, 2)} × 24% = ${eur(b.tax, 2)}. In a town without a recent revision the percentage is 2%, so that owner pays ${eur(c2.tax, 2)}. Bought on 2 July and owned 183 days, the first case comes to ${eur(half.tax, 2)}.`,
        `Valor catastral de ${eur(40000)}, en un municipio que revisó sus valores en los últimos diez años, en propiedad todo el año. Renta imputada: ${eur(40000)} × 1,1 % = ${eur(a.base, 2)}. Cuota de un residente en la UE: ${eur(a.base, 2)} × 19 % = ${eur(a.tax, 2)}. De un residente en el Reino Unido o en Estados Unidos: ${eur(a.base, 2)} × 24 % = ${eur(b.tax, 2)}. En un municipio sin revisión reciente el porcentaje es el 2 %, y ese propietario paga ${eur(c2.tax, 2)}. Comprada el 2 de julio y con 183 días en propiedad, el primer caso se queda en ${eur(half.tax, 2)}.`))}</p>`,
      how: [
        esc(t("Imputed income = cadastral value × 1.1% if the town's cadastral values were revised in the tax year or the ten before it (the rule also covers 2023 to 2026), or × 2% otherwise. No expenses are deducted.", "Renta imputada = valor catastral × 1,1 % si los valores catastrales del municipio se revisaron en el ejercicio o en los diez anteriores (la norma cubre también de 2023 a 2026), o × 2 % en el resto. No se deduce ningún gasto.")),
        esc(t("Tax = imputed income × 19% for residents of the EU, Iceland, Norway and Liechtenstein, × 24% for other taxpayers.", "Cuota = renta imputada × 19 % para residentes en la UE, Islandia, Noruega y Liechtenstein, × 24 % para los demás contribuyentes.")),
        esc(t("The amount is for a full calendar year and is reduced in proportion to the days you did not own the home or had it let. With several owners, each declares their share.", "El importe corresponde al año natural completo y se reduce en proporción a los días en que la vivienda no fue tuya o estuvo alquilada. Si hay varios propietarios, cada uno declara su parte.")),
        esc(t("If the home has no cadastral value yet, the base is 50% of the purchase price (or of the value set by the tax office, if higher), at 1.1%.", "Si la vivienda aún no tiene valor catastral, la base es el 50 % del precio de compra (o del valor comprobado por la Administración, si es mayor), al 1,1 %.")),
        esc(t("It is declared on form 210 for the previous year. It is a different tax from the IBI, which the town charges, and from the tax on rent, which applies to the days the home is let.", "Se declara en el modelo 210 por el año anterior. Es un impuesto distinto del IBI, que cobra el ayuntamiento, y del que grava el alquiler, que se aplica a los días en que la vivienda está arrendada.")),
      ],
      sources: [{ label: t("Spanish Tax Agency, non-resident income tax: imputed income from an urban property for own use", "Agencia Tributaria, IRNR: renta imputada de inmuebles urbanos de uso propio"), url: IRNR.source }, costSrc(t("IBI and the other yearly costs in Spain, with sources (RealHunt)", "IBI y demás gastos anuales en España, con fuentes (RealHunt)"), "spain")],
      faq: [
        [t("Do I pay tax in Spain if I never let my holiday home?", "¿Pago impuestos en España si nunca alquilo mi casa de vacaciones?"), esc(t(`Yes. A non-resident who owns an urban home for own use, or leaves it empty, declares an imputed income every year. On a cadastral value of ${eur(40000)} it is between ${eur(a.tax, 2)} and ${eur(c2.tax, 2)} depending on where you live and on the town.`, `Sí. Un no residente con una vivienda urbana de uso propio, o vacía, declara cada año una renta imputada. Con un valor catastral de ${eur(40000)}, sale entre ${eur(a.tax, 2)} y ${eur(c2.tax, 2)} según dónde vivas y según el municipio.`))],
        [t("Where do I find the cadastral value?", "¿Dónde encuentro el valor catastral?"), esc(t("On the IBI bill the town hall sends every year, under the heading valor catastral. It is usually well below the market price.", "En el recibo del IBI que envía el ayuntamiento cada año, en la casilla del valor catastral. Suele quedar muy por debajo del precio de mercado."))],
        [t("Is this the only yearly tax on the home?", "¿Es el único impuesto anual de la vivienda?"), t(`No. The IBI and the waste charge go to the town hall. The <a href="/tools/home-running-costs">running costs calculator</a> adds everything up, and the <a href="/guide/spain">Spain buying guide</a> explains the steps.`, `No. El IBI y la tasa de basuras van al ayuntamiento. La <a href="/tools/home-running-costs">calculadora de gastos anuales</a> lo suma todo, y la <a href="/guide/spain">guía para comprar en España</a> explica los pasos.`)],
      ],
    });
  }

  // ------------------------------------------------------------ Schengen
  {
    const stays: [string, string][] = [["2026-03-01", "2026-04-30"], ["2026-07-01", "2026-07-20"]];
    const r = schengen(stays, "2026-08-01"); const r2 = schengen(stays, "2026-09-01");
    if (!r.ok || !r2.ok) throw new Error("schengen example");
    pages.push({
      tool: "schengen", path: "/tools/schengen-90-180", embed: "schengen-90-180", now: true, data: { today: x.today }, read: SCHENGEN.read,
      base: { d: "2026-08-01", s1a: stays[0][0], s1b: stays[0][1], s2a: stays[1][0], s2b: stays[1][1] },
      title: t("Schengen 90/180 day calculator for second-home owners", "Calculadora de días Schengen (regla 90/180)"),
      h1: t("Schengen 90/180 calculator: how many days you can spend at your home", "Calculadora Schengen 90/180: cuántos días puedes pasar en tu casa"),
      desc: t("Owning a home in the Schengen area does not lift the 90 days in any 180. Enter your stays and a date: days used, days left and how long you could stay from that day.", "Tener casa en el espacio Schengen no elimina el límite de 90 días en cada 180. Escribe tus estancias y una fecha: días usados, días que quedan y cuánto podrías quedarte."),
      card: t("Days used and days left under the 90 days in any 180 rule, for owners without a residence permit.", "Días usados y días que quedan con la regla de 90 días en cada 180, para propietarios sin permiso de residencia."),
      lead: esc(t(`Buying a home in Spain, Italy, France or Greece gives no extra days: a visitor from outside the EU can be in the Schengen area for 90 days in any 180-day period, and every day at the house counts. With the two stays in the example, ${r.used} days are used on ${k.date("2026-08-01")} and ${r.left} are left. Replace them with your own dates.`,
        `Comprar una casa en España, Italia, Francia o Grecia no da días de más: un visitante de fuera de la UE puede estar en el espacio Schengen 90 días en cualquier periodo de 180, y cada día en la casa cuenta. Con las dos estancias del ejemplo, a ${k.date("2026-08-01")} hay ${r.used} días usados y quedan ${r.left}. Cámbialas por tus fechas.`)),
      example: `<p>${esc(t(`Two stays: ${k.date(stays[0][0])} to ${k.date(stays[0][1])} (61 days) and ${k.date(stays[1][0])} to ${k.date(stays[1][1])} (20 days). On ${k.date("2026-08-01")} the 180 days counted run from ${k.date(r.from)}, so both stays are inside: ${r.used} days used, ${r.left} left, and entering that day you could stay ${r.can} days, until ${k.date(r.lastDay!)}. A month later, on ${k.date("2026-09-01")}, the first days of March have dropped out of the period: ${r2.used} used, and you could stay ${r2.can} days.`,
        `Dos estancias: del ${k.date(stays[0][0])} al ${k.date(stays[0][1])} (61 días) y del ${k.date(stays[1][0])} al ${k.date(stays[1][1])} (20 días). A ${k.date("2026-08-01")}, los 180 días que se cuentan empiezan el ${k.date(r.from)}, así que entran las dos: ${r.used} días usados, quedan ${r.left}, y entrando ese día podrías quedarte ${r.can} días, hasta el ${k.date(r.lastDay!)}. Un mes después, a ${k.date("2026-09-01")}, los primeros días de marzo ya han salido del periodo: ${r2.used} usados, y podrías quedarte ${r2.can} días.`))}</p>`,
      how: [
        esc(t("The European Commission's wording: you must count back 180 days from each day of your stay and make sure the total does not exceed 90. The period moves forward one day at a time; it is not a calendar half-year.", "La Comisión Europea lo explica así: hay que contar 180 días hacia atrás desde cada día de la estancia y comprobar que el total no pasa de 90. El periodo avanza día a día; no es un semestre natural.")),
        esc(t("This calculator counts the day of entry and the day of exit as days of stay, and looks at the 180 days that end on the date you choose.", "Esta calculadora cuenta como días de estancia tanto el de entrada como el de salida, y mira los 180 días que terminan en la fecha que elijas.")),
        esc(t("\"You can stay\" adds one day at a time from that date and stops before the count passes 90. It assumes you do not leave in between.", "«Puedes quedarte» va sumando un día tras otro desde esa fecha y se detiene antes de que la cuenta pase de 90. Supone que no sales entre medias.")),
        esc(t("Days spent with a residence permit or a long-stay visa of a Schengen country are not counted and should not be entered. Citizens of the EU, Iceland, Liechtenstein, Norway and Switzerland are not subject to the rule.", "Los días pasados con un permiso de residencia o un visado de larga duración de un país Schengen no cuentan y no deben introducirse. Los ciudadanos de la UE, Islandia, Liechtenstein, Noruega y Suiza no están sujetos a la regla.")),
        esc(t("Up to six stays fit in the form, enough for the last 180 days of most owners. The Commission's own calculator, linked below, is the reference.", "En el formulario caben hasta seis estancias, suficiente para los últimos 180 días de la mayoría de propietarios. La calculadora de la propia Comisión, enlazada abajo, es la referencia.")),
      ],
      sources: [{ label: t("European Commission, Migration and Home Affairs: short-stay calculator and the 90/180-day rule (page dated 13 November 2025)", "Comisión Europea, Migración y Asuntos de Interior: calculadora de estancias cortas y regla de 90/180 días (página de 13 de noviembre de 2025)"), url: SCHENGEN.source }],
      faq: [
        [t("Does owning a home in Spain or Italy let me stay longer than 90 days?", "¿Tener casa en España o Italia me permite quedarme más de 90 días?"), t(`No. Owning property gives no right to stay. To spend more than 90 days in any 180 you need a visa or a residence permit of that country. The rules for each country and nationality are in <a href="/can-i-buy">can I buy there?</a>`, `No. Ser propietario no da derecho a quedarse. Para pasar más de 90 días en cada 180 necesitas un visado o un permiso de residencia de ese país. Las normas de cada país y nacionalidad están en <a href="/can-i-buy">¿puedo comprar allí?</a>`)],
        [t("Do the 90 days reset when I leave?", "¿Los 90 días se reinician al salir?"), esc(t("No. Leaving does not reset anything: each day only stops counting 180 days after it was spent. That is why two long summers in a row can overlap.", "No. Salir no reinicia nada: cada día solo deja de contar 180 días después de haberlo pasado. Por eso dos veranos largos seguidos pueden solaparse."))],
        [t("Which countries count?", "¿Qué países cuentan?"), esc(t("All the countries of the Schengen area together: days in France and days in Spain add up to the same 90. Ireland and Cyprus are in the EU but outside Schengen and keep their own limits.", "Todos los países del espacio Schengen a la vez: los días en Francia y los días en España suman para los mismos 90. Irlanda y Chipre están en la UE pero fuera de Schengen y tienen sus propios límites."))],
      ],
    });
  }

  // ------------------------------------------------------------ area units
  {
    const c = convertArea(100, "sqm"), ts = convertArea(30, "tsubo"), ft = convertArea(1000, "sqft"), jo = convertArea(6, "jo");
    pages.push({
      tool: "area", path: "/tools/area-converter", embed: "area-converter", data: {}, read: READ,
      title: t("Area converter: m², sq ft, tsubo and tatami", "Conversor de superficie: m², pies², tsubo y tatami"),
      h1: t("Area converter for house hunters: square metres, square feet, tsubo and tatami", "Conversor de superficie para buscar casa: metros cuadrados, pies cuadrados, tsubo y tatamis"),
      desc: t(`Convert the size of a home between square metres, square feet, Japanese tsubo and tatami mats, acres and hectares. 100 m² is ${f.num(c.sqft)} sq ft and ${f.trim(c.tsubo, 2)} tsubo.`, `Convierte la superficie de una casa entre metros cuadrados, pies cuadrados, tsubo y tatamis japoneses, acres y hectáreas. 100 m² son ${f.num(c.sqft)} pies cuadrados y ${f.trim(c.tsubo, 2)} tsubo.`),
      card: t("Square metres, square feet, Japanese tsubo and tatami mats, acres and hectares.", "Metros cuadrados, pies cuadrados, tsubo y tatamis japoneses, acres y hectáreas."),
      lead: esc(t(`A 100 m² home is ${f.num(c.sqft)} square feet, ${f.trim(c.tsubo, 2)} tsubo or about ${f.trim(c.jo, 1)} tatami mats. Listings in the United States and the United Kingdom use square feet, Japanese ones use tsubo for land and tatami mats for rooms, and most of Europe uses square metres.`,
        `Una casa de 100 m² son ${f.num(c.sqft)} pies cuadrados, ${f.trim(c.tsubo, 2)} tsubo o unos ${f.trim(c.jo, 1)} tatamis. Los anuncios de Estados Unidos y del Reino Unido usan pies cuadrados, los japoneses usan tsubo para el terreno y tatamis para las habitaciones, y casi toda Europa usa metros cuadrados.`)),
      example: `<p>${esc(t(`A Japanese listing gives a plot of 30 tsubo and a main room of 6 mats. 30 tsubo × 400/121 = ${f.trim(ts.sqm, 1)} m² (${f.num(ts.sqft)} sq ft). 6 mats × 1.62 = ${f.trim(jo.sqm, 2)} m², the least that room can measure. An American listing of 1,000 sq ft is ${f.trim(ft.sqm, 1)} m², or ${f.trim(ft.tsubo, 1)} tsubo.`,
        `Un anuncio japonés indica un terreno de 30 tsubo y una sala principal de 6 tatamis. 30 tsubo × 400/121 = ${f.trim(ts.sqm, 1)} m² (${f.num(ts.sqft)} pies cuadrados). 6 tatamis × 1,62 = ${f.trim(jo.sqm, 2)} m², lo mínimo que puede medir esa sala. Un anuncio estadounidense de 1.000 pies cuadrados son ${f.trim(ft.sqm, 1)} m², o ${f.trim(ft.tsubo, 1)} tsubo.`))}</p>`,
      how: [
        esc(t("1 square foot = 0.09290304 m² exactly (the foot is 0.3048 m), so 1 m² = 10.7639 sq ft.", "1 pie cuadrado = 0,09290304 m² exactos (el pie mide 0,3048 m), así que 1 m² = 10,7639 pies cuadrados.")),
        esc(t("1 tsubo = 400/121 m², about 3.306 m²: a square of 6 by 6 shaku, the old Japanese foot of 10/33 m. It is roughly the area of two tatami mats.", "1 tsubo = 400/121 m², unos 3,306 m²: un cuadrado de 6 por 6 shaku, el antiguo pie japonés de 10/33 m. Equivale más o menos a dos tatamis.")),
        esc(t("1 tatami mat (jō) = 1.62 m² here. That is the minimum per mat that Japanese property adverts must use when they state a room size in mats; real mats differ by region, so treat the result as a floor.", "1 tatami (jō) = 1,62 m² aquí. Es el mínimo por tatami que deben usar los anuncios inmobiliarios japoneses cuando dan el tamaño de una habitación en tatamis; los tatamis reales cambian según la región, así que toma el resultado como un mínimo.")),
        esc(t("1 acre = 4,046.8564 m²; 1 hectare = 10,000 m².", "1 acre = 4.046,8564 m²; 1 hectárea = 10.000 m².")),
      ],
      sources: [{ label: t("Real Estate Fair Trade Council of Japan, enforcement rules of the Fair Competition Code on Real Estate Representations (one mat: 1.62 m² or more; in Japanese)", "Consejo de Comercio Justo Inmobiliario de Japón, reglamento del Código de Competencia Leal sobre publicidad inmobiliaria (un tatami: 1,62 m² o más; en japonés)"), url: AREA_SOURCE }],
      faq: [
        [t("How many square feet is 100 square metres?", "¿Cuántos pies cuadrados son 100 metros cuadrados?"), esc(t(`${f.num(c.sqft)} square feet. To go the other way, 1,000 sq ft is ${f.trim(ft.sqm, 1)} m².`, `${f.num(c.sqft)} pies cuadrados. En sentido contrario, 1.000 pies cuadrados son ${f.trim(ft.sqm, 1)} m².`))],
        [t("How big is one tsubo?", "¿Cuánto mide un tsubo?"), t(`About 3.306 m² or 35.58 sq ft. Japanese land and house prices are often quoted per tsubo; see the <a href="/homes/japan">homes in Japan</a> with their size in square metres.`, `Unos 3,306 m² o 35,58 pies cuadrados. En Japón los precios del suelo y de las casas suelen darse por tsubo; mira las <a href="/homes/japan">casas en Japón</a> con su superficie en metros cuadrados.`)],
        [t("Is the size in a listing the usable floor area?", "¿La superficie de un anuncio es la útil?"), esc(t("Not always. Some countries advertise the built area with walls and a share of common parts, others the usable area. Ask which one before comparing prices per square metre.", "No siempre. En unos países se anuncia la superficie construida, con muros y parte de las zonas comunes, y en otros la útil. Pregunta cuál es antes de comparar precios por metro cuadrado."))],
      ],
    });
  }

  // ------------------------------------------------------------ mortgage or cash
  {
    const d = { price: 80000, down: 30, rate: 4, years: 20 }, r = mortgageOrCash(d), short = mortgageOrCash({ ...d, years: 10 }), m = (n: number) => f.num(n);
    pages.push({
      tool: "mortgage", path: "/tools/mortgage-or-cash", embed: "mortgage-or-cash", data: {}, read: READ,
      title: t("Mortgage or cash for a cheap home? Calculator", "¿Hipoteca o contado para una casa barata?"),
      h1: t("Mortgage or cash: what a loan adds to the price of a cheap home", "Hipoteca o al contado: lo que añade un préstamo al precio de una casa barata"),
      desc: t(`Compare paying a home in cash with a mortgage: monthly payment, total interest and what you keep in hand. ${m(d.price)} home, 30% down, 4% over 20 years: ${m(r.monthly)} a month.`, `Hipoteca o contado: cuota mensual, intereses totales y dinero que conservas. Casa de ${m(d.price)}, 30 % de entrada, al 4 % a 20 años: ${m(r.monthly)} al mes.`),
      card: t("Monthly payment, total interest and the cash you keep, against paying everything on day one.", "Cuota mensual, intereses totales y dinero que conservas, frente a pagarlo todo el primer día."),
      lead: esc(t(`On a home of ${m(d.price)} with 30% down, a loan of ${m(r.loan)} at 4% over 20 years costs ${m(r.monthly)} a month and ${m(r.interest)} of interest in total: you end up paying ${m(r.totalMortgage)} instead of ${m(d.price)}, and in exchange you keep ${m(r.kept)} in hand on the day you buy. Use the rate a bank has actually offered you.`,
        `En una casa de ${m(d.price)} con un 30 % de entrada, un préstamo de ${m(r.loan)} al 4 % a 20 años cuesta ${m(r.monthly)} al mes y ${m(r.interest)} de intereses en total: acabas pagando ${m(r.totalMortgage)} en vez de ${m(d.price)}, y a cambio conservas ${m(r.kept)} el día de la compra. Usa el tipo que te haya ofrecido de verdad un banco.`)),
      example: `<p>${esc(t(`The same loan over 10 years: ${m(short.monthly)} a month and ${m(short.interest)} of interest, ${m(r.interest - short.interest)} less than over 20 years. The monthly payment rises by ${m(short.monthly - r.monthly)}; the home costs ${m(short.totalMortgage)} in total. In cash it costs ${m(d.price)} and no interest, but the ${m(r.kept)} you would have borrowed are no longer in your account.`,
        `El mismo préstamo a 10 años: ${m(short.monthly)} al mes y ${m(short.interest)} de intereses, ${m(r.interest - short.interest)} menos que a 20 años. La cuota sube ${m(short.monthly - r.monthly)}; la casa cuesta ${m(short.totalMortgage)} en total. Al contado cuesta ${m(d.price)} y ningún interés, pero los ${m(r.kept)} que habrías pedido prestados ya no están en tu cuenta.`))}</p>`,
      how: [
        esc(t("Loan = price − down payment. Monthly payment = loan × r ÷ (1 − (1 + r)^−n), with r the yearly rate divided by 12 and n the number of months. It is the same formula as the mortgage box on every home page.", "Préstamo = precio − entrada. Cuota mensual = préstamo × r ÷ (1 − (1 + r)^−n), donde r es el tipo anual dividido entre 12 y n el número de meses. Es la misma fórmula que la del cuadro de hipoteca de cada casa.")),
        esc(t("Interest = monthly payment × months − loan. Extra cost of the loan = interest + the cost of setting it up, if you enter one.", "Intereses = cuota × meses − préstamo. Coste extra del préstamo = intereses + los gastos de abrirlo, si los indicas.")),
        esc(t("The rate is fixed for the whole term and is yours to type: the calculator has no rate of its own and does not guess what rates or prices will do.", "El tipo es fijo durante todo el plazo y lo escribes tú: la calculadora no tiene ningún tipo propio ni adivina qué harán los tipos o los precios.")),
        esc(t("Taxes and fees of the purchase are the same with or without a loan, so they are left out. Add them with the buying costs calculator.", "Los impuestos y gastos de la compra son los mismos con préstamo o sin él, así que no se incluyen. Súmalos con la calculadora de gastos de compra.")),
      ],
      sources: [{ label: t("Buying costs by country, to add to either option (RealHunt)", "Gastos de compra por país, para sumar a cualquiera de las dos opciones (RealHunt)"), url: k.url("/buying-costs") }],
      faq: [
        [t("Can I get a mortgage on a very cheap home abroad?", "¿Puedo conseguir una hipoteca para una casa muy barata en el extranjero?"), esc(t("Often not. Many banks set a minimum loan, lend a smaller share of the price to non-residents and refuse homes that need work. That is why most cheap homes are bought in cash. Ask a bank of the country before you make an offer that depends on a loan.", "Muchas veces no. Muchos bancos fijan un préstamo mínimo, prestan a los no residentes una parte menor del precio y rechazan casas que necesitan obras. Por eso la mayoría de las casas baratas se compran al contado. Pregunta a un banco del país antes de hacer una oferta que dependa de un préstamo."))],
        [t("Is paying in cash always cheaper?", "¿Pagar al contado sale siempre más barato?"), esc(t(`In money paid for the home, yes: the loan in the example adds ${m(r.interest)}. Whether that is worth it depends on what else you need the cash for, such as repairs, the taxes of the purchase and a reserve. The calculator shows both numbers and leaves the decision to you.`, `En dinero pagado por la casa, sí: el préstamo del ejemplo añade ${m(r.interest)}. Que compense depende de para qué más necesites el dinero, como las reformas, los impuestos de la compra y una reserva. La calculadora enseña las dos cifras y te deja la decisión.`))],
        [t("Does a mortgage change the taxes of the purchase?", "¿La hipoteca cambia los impuestos de la compra?"), t(`The transfer tax or VAT is the same. A loan adds its own costs (valuation, bank fees, sometimes a tax on the mortgage deed). See the <a href="/buying-costs">buying costs calculator</a> for the purchase itself.`, `El impuesto de transmisiones o el IVA es el mismo. El préstamo añade sus propios gastos (tasación, comisiones del banco, a veces un impuesto sobre la escritura de hipoteca). Mira la <a href="/buying-costs">calculadora de gastos de compra</a> para la compra en sí.`)],
      ],
    });
  }

  // ------------------------------------------------------------ years of your rent
  {
    const d = { price: 80000, rent: 1000, costsPct: 10 }, r = rentYears(d), hi = rentYears({ ...d, rent: 1500 }), m = (n: number) => f.num(n);
    pages.push({
      tool: "rent", path: "/tools/years-of-rent", embed: "years-of-rent", data: {}, read: READ,
      title: t("How many years of rent does a cheap home cost?", "¿Cuántos años de alquiler cuesta una casa barata?"),
      h1: t("Years of rent: what a cheap home costs in the rent you pay today", "Años de alquiler: lo que cuesta una casa barata en el alquiler que pagas hoy"),
      desc: t(`Type the price of a home and the rent you pay: see how many years of that rent add up to the home with its taxes and fees. ${m(d.price)} home, ${m(d.rent)} a month: ${f.trim(r.years, 1)} years.`, `Escribe el precio de una casa y tu alquiler: mira cuántos años de ese alquiler suman la casa con impuestos y gastos. Casa de ${m(d.price)}, ${m(d.rent)} al mes: ${f.trim(r.years, 1)} años.`),
      card: t("The price of a home, with its taxes and fees, counted in years of the rent you pay now.", "El precio de una casa, con sus impuestos y gastos, contado en años del alquiler que pagas ahora."),
      lead: esc(t(`A home of ${m(d.price)} with 10% of taxes and fees costs ${m(r.total)} in total. At a rent of ${m(d.rent)} a month, that is ${f.num(r.months)} months of rent, or ${f.trim(r.years, 1)} years. Type your own rent and the price of the home you are looking at.`,
        `Una casa de ${m(d.price)} con un 10 % de impuestos y gastos cuesta ${m(r.total)} en total. Con un alquiler de ${m(d.rent)} al mes, son ${f.num(r.months)} meses de alquiler, es decir, ${f.trim(r.years, 1)} años. Escribe tu alquiler y el precio de la casa que estás mirando.`)),
      example: `<p>${esc(t(`The same home against a rent of ${m(hi.year / 12)} a month: ${f.num(hi.months)} months, or ${f.trim(hi.years, 1)} years. One year of that rent is ${m(hi.year)}, so the home with its taxes and fees costs ${f.trim(hi.years, 1)} times a year of rent.`,
        `La misma casa frente a un alquiler de ${m(hi.year / 12)} al mes: ${f.num(hi.months)} meses, es decir, ${f.trim(hi.years, 1)} años. Un año de ese alquiler son ${m(hi.year)}, así que la casa con sus impuestos y gastos cuesta ${f.trim(hi.years, 1)} veces un año de alquiler.`))}</p>`,
      how: [
        esc(t("Total to buy = price × (1 + taxes and fees ÷ 100). Years of rent = total ÷ (monthly rent × 12). Months are rounded up to the next whole month.", "Total para comprar = precio × (1 + impuestos y gastos ÷ 100). Años de alquiler = total ÷ (alquiler mensual × 12). Los meses se redondean al mes entero siguiente.")),
        esc(t("The share of taxes and fees is yours to type. It changes a lot from one country to another: use the buying costs calculator for the country of the home.", "El porcentaje de impuestos y gastos lo escribes tú. Cambia mucho de un país a otro: usa la calculadora de gastos de compra del país de la casa.")),
        esc(t("The calculator compares two amounts and does not guess what rents, prices or interest rates will do.", "La calculadora compara dos cantidades y no adivina qué harán los alquileres, los precios ni los tipos de interés.")),
      ],
      sources: [{ label: t("Buying costs by country, for the share of taxes and fees (RealHunt)", "Gastos de compra por país, para el porcentaje de impuestos y gastos (RealHunt)"), url: k.url("/buying-costs") }],
      faq: [
        [t("Does this mean buying is better than renting?", "¿Significa esto que comprar es mejor que alquilar?"), esc(t("No. It only shows the size of the price next to a number you know well. An owner also pays yearly property tax, insurance, repairs and travel to the home, and a home abroad does not replace the place where you work.", "No. Solo enseña el tamaño del precio junto a una cifra que conoces bien. Un propietario también paga cada año impuesto sobre la propiedad, seguro, reparaciones y viajes a la casa, y una casa en el extranjero no sustituye el lugar donde trabajas."))],
        [t("What does a home cost every year after buying?", "¿Qué cuesta una casa cada año después de comprarla?"), t(`It depends on the home. Add up your own figures with the <a href="/tools/home-running-costs">running costs calculator</a>.`, `Depende de la casa. Suma tus propias cifras con la <a href="/tools/home-running-costs">calculadora de gastos de mantener una casa</a>.`)],
        [t("Which rent should I type?", "¿Qué alquiler debo escribir?"), esc(t("The rent you pay each month for your home today, without bills. If you share the rent, type your part and compare it with your part of the price.", "El alquiler que pagas cada mes por tu vivienda hoy, sin suministros. Si compartes el alquiler, escribe tu parte y compárala con tu parte del precio."))],
      ],
    });
  }

  // ------------------------------------------------------------ sell your home and buy a cheaper one
  {
    const d = { value: 300000, debt: 0, sellPct: 5, price: 80000, buyPct: 10 }, r = sellAndMove(d), debt = sellAndMove({ ...d, debt: 120000 }), m = (n: number) => f.num(n);
    pages.push({
      tool: "move", path: "/tools/sell-and-move", embed: "sell-and-move", data: {}, read: READ,
      title: t("Sell your home and buy a cheaper one abroad: calculator", "Vender tu casa y comprar una más barata fuera"),
      h1: t("Sell and move: what is left after buying a cheaper home", "Vender y mudarse: lo que te sobra después de comprar una casa más barata"),
      desc: t(`Type what your home would sell for and the price of the home you would buy: see the cash left once the costs of selling and of buying are paid. Sell at ${m(d.value)}, buy at ${m(d.price)}: ${m(r.left)} left.`, `Escribe por cuánto venderías tu casa y el precio de la que comprarías: mira lo que te sobra pagados los gastos de vender y comprar. Vendes por ${m(d.value)}, compras por ${m(d.price)}: te sobran ${m(r.left)}.`),
      card: t("The sale of your home, minus its costs and your mortgage, against a cheaper home with its taxes and fees.", "La venta de tu casa, menos sus gastos y tu hipoteca, frente a una casa más barata con sus impuestos y gastos."),
      lead: esc(t(`Selling a home for ${m(d.value)} with 5% of selling costs leaves ${m(r.cash)}. A home of ${m(d.price)} with 10% of taxes and fees costs ${m(r.total)}, so ${m(r.left)} are left over. Type your own figures, including the mortgage you still owe.`,
        `Vender una casa por ${m(d.value)} con un 5 % de gastos de venta deja ${m(r.cash)}. Una casa de ${m(d.price)} con un 10 % de impuestos y gastos cuesta ${m(r.total)}, así que te sobran ${m(r.left)}. Escribe tus propias cifras, incluida la hipoteca que aún debes.`)),
      example: `<p>${esc(t(`The same sale with ${m(120000)} of mortgage still owed: the sale leaves ${m(debt.cash)} and, after buying the home of ${m(d.price)} with its costs, ${m(debt.left)} are left over. The mortgage comes out of the sale before anything else.`,
        `La misma venta con ${m(120000)} de hipoteca pendiente: la venta deja ${m(debt.cash)} y, después de comprar la casa de ${m(d.price)} con sus gastos, te sobran ${m(debt.left)}. La hipoteca sale de la venta antes que nada.`))}</p>`,
      how: [
        esc(t("Cash from the sale = sale price − costs of selling − mortgage still owed. Costs of selling = sale price × the share you type (agent, lawyer, certificates).", "Dinero de la venta = precio de venta − gastos de vender − hipoteca pendiente. Gastos de vender = precio de venta × el porcentaje que escribas (agencia, abogado, certificados).")),
        esc(t("New home in total = price × (1 + taxes and fees ÷ 100). Left over = cash from the sale − new home in total.", "Casa nueva en total = precio × (1 + impuestos y gastos ÷ 100). Lo que sobra = dinero de la venta − casa nueva en total.")),
        esc(t("Tax on the gain of the sale is left out: the rules differ by country and by person. Ask a tax adviser before you count on the full amount.", "El impuesto sobre la ganancia de la venta no se incluye: las reglas cambian según el país y la persona. Consulta a un asesor fiscal antes de contar con el importe completo.")),
      ],
      sources: [{ label: t("Buying costs by country, for the share of taxes and fees (RealHunt)", "Gastos de compra por país, para el porcentaje de impuestos y gastos (RealHunt)"), url: k.url("/buying-costs") }],
      faq: [
        [t("Is the money left over mine to spend?", "¿El dinero que sobra es mío para gastar?"), esc(t("Not all of it, as a rule. Many countries tax the gain of a sale, some let you off when the money goes into another main home, and moving has its own costs. Keep a reserve for repairs and for the first year of bills.", "Por lo general, no todo. Muchos países gravan la ganancia de una venta, algunos la eximen si el dinero va a otra vivienda habitual, y mudarse tiene sus propios gastos. Guarda una reserva para reparaciones y para las facturas del primer año."))],
        [t("Can I live in the country of the new home?", "¿Puedo vivir en el país de la casa nueva?"), t(`Owning a home does not give the right to live there. See <a href="/can-i-buy">who can buy in each country</a> and, for stays in the Schengen area, the <a href="/tools/schengen-90-180">90 days in 180 calculator</a>.`, `Ser propietario no da derecho a vivir allí. Mira <a href="/can-i-buy">quién puede comprar en cada país</a> y, para estancias en el espacio Schengen, la <a href="/tools/schengen-90-180">calculadora de 90 días en 180</a>.`)],
        [t("What share should I type for the costs of selling?", "¿Qué porcentaje pongo para los gastos de vender?"), esc(t("The fee your agent has quoted plus the lawyer or notary and the certificates your country asks for. Five percent is a starting point, not a rule.", "La comisión que te haya dado tu agencia más el abogado o notario y los certificados que pida tu país. Un cinco por ciento es un punto de partida, no una regla."))],
      ],
    });
  }
  return pages;
}
